import bcrypt from "bcryptjs";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
};

type StoredUser = User & { passwordHash: string | null };

// In-memory store. Passwords are hashed with bcrypt before landing here —
// callers never see or pass around plaintext beyond createUser/verifyPassword.
const users: StoredUser[] = [
  {
    id: "1",
    email: "ada@example.com",
    name: "Ada",
    createdAt: "2026-01-04",
    passwordHash: null,
  },
  {
    id: "2",
    email: "grace@example.com",
    name: "Grace",
    createdAt: "2026-02-11",
    passwordHash: null,
  },
];

let nextId = users.length + 1;

function toPublicUser({ passwordHash: _passwordHash, ...user }: StoredUser): User {
  return user;
}

export async function listUsers(): Promise<User[]> {
  return users.map(toPublicUser);
}

export async function getUser(id: string): Promise<User | undefined> {
  const user = users.find((u) => u.id === id);
  return user ? toPublicUser(user) : undefined;
}

export async function getUserByEmail(email: string): Promise<User | undefined> {
  const user = users.find((u) => u.email.toLowerCase() === email.toLowerCase());
  return user ? toPublicUser(user) : undefined;
}

// Creates an email+password account. Throws if the email is already taken.
export async function createUser(params: {
  email: string;
  name: string;
  password: string;
}): Promise<User> {
  const email = params.email.toLowerCase();
  if (users.some((u) => u.email.toLowerCase() === email)) {
    throw new Error("An account with this email already exists");
  }
  const passwordHash = await bcrypt.hash(params.password, 10);
  const user: StoredUser = {
    id: String(nextId++),
    email,
    name: params.name,
    createdAt: new Date().toISOString().slice(0, 10),
    passwordHash,
  };
  users.push(user);
  return toPublicUser(user);
}

// Verifies email+password credentials. Returns null on any mismatch,
// including accounts that only have Google sign-in (no passwordHash).
export async function verifyPassword(
  email: string,
  password: string
): Promise<User | null> {
  const user = users.find((u) => u.email.toLowerCase() === email.toLowerCase());
  if (!user || !user.passwordHash) return null;
  const valid = await bcrypt.compare(password, user.passwordHash);
  return valid ? toPublicUser(user) : null;
}

// Finds or creates the user record for an OAuth (Google) sign-in.
export async function upsertOAuthUser(params: {
  email: string;
  name: string;
}): Promise<User> {
  const email = params.email.toLowerCase();
  const existing = users.find((u) => u.email.toLowerCase() === email);
  if (existing) return toPublicUser(existing);
  const user: StoredUser = {
    id: String(nextId++),
    email,
    name: params.name,
    createdAt: new Date().toISOString().slice(0, 10),
    passwordHash: null,
  };
  users.push(user);
  return toPublicUser(user);
}

